import{_ as a,o as t,c as i,a5 as o}from"./chunks/framework.DbSlGjul.js";const u=JSON.parse('{"title":"Data collection with DataHive","description":"Collect, annotate, validate, and share HiveBoard learning episodes with DataHive, including data collected during benchmark evaluations.","frontmatter":{"description":"Collect, annotate, validate, and share HiveBoard learning episodes with DataHive, including data collected during benchmark evaluations."},"headers":[],"relativePath":"guides/datahive.md","filePath":"guides/datahive.md","lastUpdated":1790086246000}'),s={name:"guides/datahive.md"};function n(r,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="data-collection-with-datahive" tabindex="-1">Data collection with DataHive <a class="header-anchor" href="#data-collection-with-datahive" aria-label="Permalink to &quot;Data collection with DataHive&quot;">​</a></h1><p><a href="https://github.com/hiveboard-bench/DataHive" target="_blank" rel="noreferrer">DataHive</a> is a toolkit for collecting HiveBoard manipulation episodes with robot states, control commands, camera recordings, and task annotations. It provides a local browser interface, a Python recording API, validation tools, and upload to a configured Hugging Face dataset repository.</p><p><strong>We encourage labs to collect learning data while running a benchmark evaluation.</strong> Recording the same trials can provide both performance measurements and trajectories for subsequent research. Dataset collection is optional: a benchmark submission still requires all 13 conditions with five trials each, while the <a href="/hivedocs/contribute/evaluations">learning-dataset call</a> has no fixed episode count or requirement to cover every condition.</p><h2 id="choose-the-workflow" tabindex="-1">Choose the workflow <a class="header-anchor" href="#choose-the-workflow" aria-label="Permalink to &quot;Choose the workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Output</th></tr></thead><tbody><tr><td><a href="/hivedocs/benchmark/evaluation-runner">Website Evaluation Runner</a></td><td>Time trials, enter outcomes, and prepare a benchmark submission in the browser</td><td>Benchmark trial CSV, platform description, and submission package</td></tr><tr><td>DataHive local Runner and Annotate pages</td><td>Organize collection sessions, connect recorded states, commands, and videos to trials, and annotate and validate episodes</td><td>HDF5 episodes, camera MP4 files, and an extended annotation CSV</td></tr></tbody></table><p>The website Evaluation Runner does not acquire robot or camera streams. DataHive requires a recording integration with your experimental system; installing the toolkit alone does not connect it to a robot.</p><h2 id="lab-registration-and-credentials" tabindex="-1">Lab registration and credentials <a class="header-anchor" href="#lab-registration-and-credentials" aria-label="Permalink to &quot;Lab registration and credentials&quot;">​</a></h2><p>All manipulation data contributed across laboratories is centralized directly in the official <strong>HiveBoard</strong> repository on Hugging Face (<code>HiveBoard/&lt;lab_id&gt;</code>). Labs do not need to create or host separate repositories; all contributions always go directly to our official benchmark Hub storage.</p><p>To receive authorization and write access to your designated repository:</p><ol><li><strong>Submit the registration form</strong>: Fill out the <a href="https://docs.google.com/forms/d/e/1FAIpQLScfDJvfcweYjv8bLDEALWOJk1q4mW3xOeB52aUey1VWWp_pxQ/viewform?usp=dialog" target="_blank" rel="noreferrer">DataHive Lab Registration Form</a> with your lab name, institution, robotic platform, and contact email.</li><li><strong>Receive credentials</strong>: The HiveBoard team will register your laboratory and provide: <ul><li>Your unique <strong>Lab ID</strong> (<code>lab_id</code>, e.g. <code>labrom</code>, <code>cmu_bimanual</code>);</li><li>An authentication <strong>Hugging Face write token</strong> allowing DataHive to upload directly to <code>HiveBoard/&lt;lab_id&gt;</code>.</li></ul></li><li><strong>Direct upload destination</strong>: All episodes uploaded through DataHive go straight to <code>HiveBoard/&lt;lab_id&gt;</code>. This ensures standardized tracking, dataset indexing, and automated aggregation for future benchmark releases.</li></ol><h2 id="install-and-configure" tabindex="-1">Install and configure <a class="header-anchor" href="#install-and-configure" aria-label="Permalink to &quot;Install and configure&quot;">​</a></h2><p>Use Python 3.10 or later in a dedicated environment. Install <code>datahive-tools</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> datahive-tools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;datahive-tools[video]&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # includes OpenCV for video integrity checks</span></span></code></pre></div><p>Initialize your lab configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>The CLI prompts for:</p><ul><li><code>Lab ID</code>: your assigned lab identifier from the registration form;</li><li><code>Hugging Face token</code>: your write token issued by the HiveBoard team.</li></ul><p><code>init</code> verifies your token against the Hugging Face Hub (via <code>whoami()</code>), writes your configuration to <code>~/.datahive/config.yaml</code> with secure <code>0600</code> file permissions, and automatically sets the remote repository destination to our official repository <code>HiveBoard/&lt;lab_id&gt;</code>.</p><p>Next, create the robot profile skeleton:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-profile</span></span></code></pre></div><p>Fill in <code>samples/robot_profile.yaml</code> before recording. Describe the robot, end-effector, control mode, state and command conventions, joint order, recording rate, and cameras. See the upstream <a href="https://github.com/hiveboard-bench/DataHive/blob/main/src/datahive/skills/datahive-data-prep/reference/robot-profile.md" target="_blank" rel="noreferrer">robot-profile reference</a> for field definitions.</p><p>From the same working directory, start the interface:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interface</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Open <code>http://127.0.0.1:8000</code> on that computer. Use <strong>Runner</strong> to plan a session or <strong>Annotate</strong> to inspect existing episodes.</p><h2 id="record-a-session" tabindex="-1">Record a session <a class="header-anchor" href="#record-a-session" aria-label="Permalink to &quot;Record a session&quot;">​</a></h2><p>Select the task conditions and collection mode. The Runner defaults to five trials per selected condition. Dataset collections can use a subset of conditions and additional sessions; the benchmark&#39;s 65-trial requirement is not a dataset-size limit.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Recording procedure</th></tr></thead><tbody><tr><td>Manual</td><td>Use the countdown and stopwatch, enter the outcome, and attach the HDF5 episode and one MP4 per camera listed in the robot profile. Your experimental system records these files.</td></tr><tr><td>Automatic</td><td>Connect your recording/control script through <code>CollectClient</code>. The script receives the queued task, writes states and commands through <code>EpisodeWriter</code>, attaches camera recordings, and returns the episode for annotation. The evaluator still determines the outcome.</td></tr></tbody></table><p>Follow the upstream <a href="https://github.com/hiveboard-bench/DataHive/blob/main/src/datahive/skills/datahive-data-prep/reference/layout-and-format.md" target="_blank" rel="noreferrer">data format</a> when preparing files. For automatic collection, use the <a href="https://github.com/hiveboard-bench/DataHive/blob/main/src/datahive/skills/datahive-auto-collect/reference/adapting.md" target="_blank" rel="noreferrer">robot integration guide</a>. Robot drivers, command generation, and camera acquisition remain part of the lab&#39;s integration.</p><div class="tip custom-block"><p class="custom-block-title">Reference integration: Franka Research 3</p><p>For a complete example to use as a base, see <a href="https://github.com/hiveboard-bench/fr3_datahive" target="_blank" rel="noreferrer"><code>fr3_datahive</code></a> for a Dockerized setup with ROS 1 Noetic, teleoperation, and DataHive recording on a Franka Research 3 (FR3).</p></div><p><strong>Record physical trials with an external camera</strong>, with the board, end-effector, and task state visible throughout. Include that camera in the profile when storing its recording with the DataHive episode. For simulation, record rendered camera observations and identify the simulator and configuration.</p><h3 id="check-the-recording-setup-first" tabindex="-1">Check the recording setup first <a class="header-anchor" href="#check-the-recording-setup-first" aria-label="Permalink to &quot;Check the recording setup first&quot;">​</a></h3><p>DataHive currently expects aligned state and command arrays in HDF5, a proprioception rate of at least 100 Hz, and one MP4 per configured camera. Its video checks require matching camera resolution, frame rate, and frame count; each image dimension must be 180–1280 pixels, and video duration must match the episode within 0.5 seconds. Check the upstream format reference when choosing acquisition settings.</p><p>Record and validate a short pilot episode before starting the collection. Preserve the original streams and timestamps and document any conversion. If your system cannot meet these constraints, discuss an alternative format with the organizers before collection. The dataset call also welcomes depth, force/torque, tactile, and other signals; agree on supplemental files for modalities outside DataHive&#39;s current episode format.</p><h2 id="annotate-and-validate" tabindex="-1">Annotate and validate <a class="header-anchor" href="#annotate-and-validate" aria-label="Permalink to &quot;Annotate and validate&quot;">​</a></h2><p>The local interface supports review and validation. The equivalent command sequence for an existing episode is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span></code></pre></div><p>Replace <code>EPISODE_ID</code> with the recorded episode identifier. <code>check</code> inspects recording integrity before annotation. <code>annotate</code> records task outcome and related fields; <code>validate</code> checks the episode and annotation together. Inspect both errors and warnings.</p><p>Use the <a href="/hivedocs/benchmark/tasks">task definitions</a> and <a href="/hivedocs/benchmark/logging">counting conventions</a> for outcomes, stages, attempts, and regrasps. Preserve unsuccessful episodes and label interventions, resets, and aborted recordings. A benchmark trial may contain several attempts or regrasps; these do not become separate scored trials.</p><h2 id="collect-during-a-benchmark-evaluation" tabindex="-1">Collect during a benchmark evaluation <a class="header-anchor" href="#collect-during-a-benchmark-evaluation" aria-label="Permalink to &quot;Collect during a benchmark evaluation&quot;">​</a></h2><ol><li>Test recording and synchronization before the scored trials. Keep familiarization and training episodes identifiable and separate from the evaluation set.</li><li>Follow the <a href="/hivedocs/benchmark/protocol">evaluation protocol</a>, including all 13 conditions, five trials per condition, fixed control settings, neutral starting poses, resets, and task timeouts. Use the required separate blocks for the two ball-valve configurations.</li><li>Record the same trial&#39;s states, commands, and camera streams. Maintain an index linking its DataHive session and episode IDs to the benchmark <code>trial_id</code> and <code>attachment_id</code>; session trial numbers may follow a different order from the benchmark template.</li><li>Time the benchmark trial from the first commanded task motion until success, a safety stop, or timeout. Save a completion time only for successful trials. A recording may include time before or after the task, so its total duration is not automatically the benchmark completion time.</li><li>Prepare the benchmark log and <a href="/hivedocs/benchmark/results">submission package</a> separately from the learning dataset. Report every scored trial, including failures, and retain the external-camera recording for each one.</li></ol><p>DataHive&#39;s <code>trials.csv</code> contains extra annotation fields and is <strong>not a drop-in replacement for the benchmark CSV</strong>. For the benchmark submission, use the website Evaluation Runner or transfer the scored results into the <a href="/hivedocs/benchmark/logging">benchmark template</a>, preserving its condition-to-trial mapping and filling all required counts and stages. Keep a correspondence to the original episode IDs. Do not copy DataHive&#39;s operator and annotator names into the public benchmark files.</p><p>To generate the benchmark submission ZIP, enter the scored results and platform details in the website Evaluation Runner. It does not currently import DataHive CSV files. The template can be used to prepare the records before entry.</p><p>Passing DataHive validation checks an episode&#39;s format and annotations; it does not establish that all 65 benchmark trials or the full evaluation protocol have been completed. Data collected during evaluation can be contributed for future training, but must remain excluded from training or tuning the policy whose performance those trials report.</p><h2 id="upload-to-hugging-face-hub" tabindex="-1">Upload to Hugging Face Hub <a class="header-anchor" href="#upload-to-hugging-face-hub" aria-label="Permalink to &quot;Upload to Hugging Face Hub&quot;">​</a></h2><p>DataHive synchronizes local manipulation sessions directly with our official Hugging Face dataset repository (<code>HiveBoard/&lt;lab_id&gt;</code>). Labs do not create external repositories; all data contributes directly to the central HiveBoard repository.</p><h3 id="upload-a-single-episode" tabindex="-1">Upload a single episode <a class="header-anchor" href="#upload-a-single-episode" aria-label="Permalink to &quot;Upload a single episode&quot;">​</a></h3><p>After reviewing and validating an episode, upload it using the CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span></code></pre></div><p>Before uploading, DataHive runs a preflight check to confirm that the episode status is <code>validated</code> and directory structure constraints are satisfied. When confirmed, DataHive:</p><ul><li>uploads the trajectory array to <code>{session_id}/episodes/{episode_id}.h5</code>;</li><li>uploads each camera recording to <code>{session_id}/episodes/{camera_name}.mp4</code>;</li><li>uploads <code>{session_id}/setup.jpg</code> if present;</li><li>automatically downloads and merges <code>{session_id}/trials.csv</code> directly in the HiveBoard repository, keeping remote records synchronized with local additions;</li><li>marks the episode status as <code>uploaded</code> in the local index (<code>samples/.datahive/index.sqlite</code>).</li></ul><p>Use <code>--yes</code> (<code>-y</code>) to skip the confirmation prompt, or <code>--force</code> to re-upload an already uploaded episode.</p><h3 id="synchronize-all-sessions-datahive-sync" tabindex="-1">Synchronize all sessions (<code>datahive sync</code>) <a class="header-anchor" href="#synchronize-all-sessions-datahive-sync" aria-label="Permalink to &quot;Synchronize all sessions (\`datahive sync\`)&quot;">​</a></h3><p>To reconcile your entire local <code>samples/</code> directory with our Hugging Face repository in one command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p><code>sync</code> scans all sessions under <code>samples/</code>, detects any validated episodes that have not yet been uploaded, pushes them directly to <code>HiveBoard/&lt;lab_id&gt;</code>, and merges all corresponding <code>trials.csv</code> files on the Hub.</p><p>Use <code>--dry-run</code> to preview what would be uploaded without transferring files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><h3 id="uploading-from-the-web-interface" tabindex="-1">Uploading from the web interface <a class="header-anchor" href="#uploading-from-the-web-interface" aria-label="Permalink to &quot;Uploading from the web interface&quot;">​</a></h3><p>Both operations are also accessible in the local web interface (<code>datahive interface</code>):</p><ul><li>In the <strong>Annotate</strong> view, click the <strong>Upload</strong> button on any validated episode card to upload it immediately to <code>HiveBoard/&lt;lab_id&gt;</code>.</li><li>In the header, click <strong>Sync</strong> to reconcile all sessions with the Hub.</li></ul><h3 id="remote-repository-layout" tabindex="-1">Remote repository layout <a class="header-anchor" href="#remote-repository-layout" aria-label="Permalink to &quot;Remote repository layout&quot;">​</a></h3><p>All contributed episodes are organized inside our official dataset repository:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HiveBoard/&lt;lab_id&gt;/                  # Official HiveBoard dataset repository</span></span>
<span class="line"><span>├── 2026-09-20_session_01/</span></span>
<span class="line"><span>│   ├── episodes/</span></span>
<span class="line"><span>│   │   ├── episode_0001.h5          # States, commands, and joint telemetry</span></span>
<span class="line"><span>│   │   ├── camera_wrist.mp4         # Synchronized camera video</span></span>
<span class="line"><span>│   │   ├── camera_external.mp4      # External view video</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   ├── trials.csv                   # Session trials and outcome annotations</span></span>
<span class="line"><span>│   └── setup.jpg                    # Platform setup photo</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><h3 id="submitting-for-organizer-review" tabindex="-1">Submitting for organizer review <a class="header-anchor" href="#submitting-for-organizer-review" aria-label="Permalink to &quot;Submitting for organizer review&quot;">​</a></h3><p>Because all uploads go directly to our official HiveBoard repository:</p><ul><li>You do not need to configure external storage, manage third-party repositories, or transfer archives manually.</li><li>When you finish collecting a session or dataset, simply email <strong><a href="mailto:ricardo.godoy@usp.br" target="_blank" rel="noreferrer">ricardo.godoy@usp.br</a></strong> with your <code>lab_id</code>, platform description, and covered tasks, as detailed in the <a href="/hivedocs/contribute/evaluations#send-the-data-for-review">dataset submission instructions</a>. The HiveBoard team will review the uploaded episodes directly in <code>HiveBoard/&lt;lab_id&gt;</code>.</li></ul><p>Record the DataHive package version or commit with the dataset. DataHive builds on the architecture and workflows of <a href="https://github.com/oopsie-data" target="_blank" rel="noreferrer">Oopsie Data</a>; see its <a href="https://github.com/hiveboard-bench/DataHive#readme" target="_blank" rel="noreferrer">README</a> for project credits and current usage.</p>`,67)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
